#!/usr/bin/env python3
"""
CONSEIL DE PHASE ACE777 - BTC | ETH | BNB
Interface Qwen 2.5-Coder avec flux marché en temps réel
"""

import ollama
import requests

def get_prices():
    symbols = ['BTCUSDT', 'ETHUSDT', 'BNBUSDT']
    prices = {}
    for s in symbols:
        try:
            url = f"https://api.binance.com/api/v3/ticker/price?symbol={s}"
            r = requests.get(url, timeout=5)
            r.raise_for_status()
            prices[s] = r.json()['price']
        except Exception:
            prices[s] = "N/A"
    return prices

print("=== CONSEIL DE PHASE ACE777 : BTC | ETH | BNB ===")
print("Tape 'exit', 'quit' ou 'stop' pour quitter.\n")

while True:
    p = get_prices()
    print(f"[STASE] BTC: {p['BTCUSDT']}$ | ETH: {p['ETHUSDT']}$ | BNB: {p['BNBUSDT']}$")

    try:
        user_msg = input("Christophe > ")
    except (EOFError, KeyboardInterrupt):
        break

    if user_msg.strip().lower() in ['exit', 'quit', 'stop']:
        break

    prompt = (
        f"CONTEXTE MARCHÉ : BTC:{p['BTCUSDT']}$ ETH:{p['ETHUSDT']}$ BNB:{p['BNBUSDT']}$\n"
        f"MESSAGE : {user_msg}\n"
        "ANALYSE ACE777 :"
    )

    try:
        stream = ollama.chat(
            model='qwen2.5-coder:1.5b',
            messages=[{'role': 'user', 'content': prompt}],
            stream=True,
        )
        print("\nACE777 > ", end="", flush=True)
        for chunk in stream:
            content = chunk.get('message', {}).get('content', '')
            if content:
                print(content, end="", flush=True)
        print("\n")
    except Exception as e:
        print(f"\nErreur de phase: {e}\n")

