pub fn extract_eth_address(text: &str) -> Option<String> {
    for word in text.split_whitespace() {
        let w = word.trim_matches(|c: char| !c.is_ascii_hexdigit() && c != 'x');
        if w.len() == 42 && w.starts_with("0x") && w[2..].chars().all(|c| c.is_ascii_hexdigit()) {
            return Some(w.to_lowercase());
        }
    }
    None
}

