//! Lecture locale du bot ACE777 (runs/, STATE.md, PnL, diagnostic ALPHA).

use anyhow::Result;
use std::path::{Path, PathBuf};

use super::detect;

fn runs_dir() -> PathBuf {
    if let Ok(p) = std::env::var("ACE777_RUNS_DIR") {
        return PathBuf::from(p);
    }
    PathBuf::from("/Users/christophe/ace777-test-day1/runs")
}

fn read_file_lossy(path: &Path, max_chars: usize) -> Option<String> {
    let raw = std::fs::read_to_string(path).ok()?;
    if raw.len() <= max_chars {
        Some(raw)
    } else {
        Some(format!("{}…\n[tronqué]", &raw[..max_chars]))
    }
}

fn read_json_field(path: &Path, fields: &[&str]) -> Vec<String> {
    let Ok(raw) = std::fs::read_to_string(path) else {
        return Vec::new();
    };
    let Ok(v) = serde_json::from_str::<serde_json::Value>(&raw) else {
        return Vec::new();
    };
    fields
        .iter()
        .filter_map(|k| v.get(k).map(|val| format!("{k}={val}")))
        .collect()
}

/// Contexte ACE777 injecté dans le prompt (fichiers locaux, pas d'API).
pub fn gather_context(user_text: &str) -> Result<String> {
    let lower = user_text.to_lowercase();
    let dir = runs_dir();
    if !dir.is_dir() {
        return Ok(format!(
            "Bot ACE777 : dossier runs introuvable (`{}`). \
             Définis ACE777_RUNS_DIR dans .env.",
            dir.display()
        ));
    }

    let mut blocks = Vec::new();
    blocks.push(format!(
        "[Bot ACE777 — données locales lues à l'instant depuis `{}`]",
        dir.display()
    ));

    if detect::wants_ace777_status(&lower) || detect::wants_ace777_bot(&lower) {
        let state = dir.join("STATE.md");
        if state.is_file() {
            if let Some(s) = read_file_lossy(&state, 4000) {
                blocks.push(format!("=== STATE.md ===\n{s}"));
            }
        } else {
            blocks.push("STATE.md absent — le bot n'a peut-être pas encore tourné.".into());
        }

        let duo = read_json_field(
            &dir.join("duo_state.json"),
            &["role", "status", "side", "bps", "pnl_usdt", "reason", "cycle"],
        );
        if !duo.is_empty() {
            blocks.push(format!("duo_state.json : {}", duo.join(", ")));
        }

        if let Some(roles) = std::fs::read_to_string(dir.join("duo_session.json"))
            .ok()
            .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok())
        {
            if let Some(r) = roles.get("roles") {
                blocks.push(format!(
                    "PnL session duo : scout={} hunter={} total={}",
                    r.get("scout").unwrap_or(&serde_json::Value::Null),
                    r.get("hunter").unwrap_or(&serde_json::Value::Null),
                    roles.get("total_pnl").unwrap_or(&serde_json::Value::Null),
                ));
            }
        }
    }

    if detect::wants_ace777_pnl(&lower) || detect::wants_ace777_bot(&lower) {
        let pnl = dir.join("RAPPORT_PNL_DERNIER.md");
        if pnl.is_file() {
            if let Some(s) = read_file_lossy(&pnl, 2500) {
                blocks.push(format!("=== Dernier rapport PnL ===\n{s}"));
            }
        }
    }

    if detect::wants_ace777_alpha_diag(&lower) {
        let diag = dir.join("DIAG_ALPHA_DERNIER.md");
        if diag.is_file() {
            if let Some(s) = read_file_lossy(&diag, 3000) {
                blocks.push(format!("=== Diagnostic ALPHA ===\n{s}"));
            }
        } else {
            blocks.push(
                "Diagnostic ALPHA absent — lance `./scripts/diagnostic_alpha.sh` dans ace777-test-day1."
                    .into(),
            );
        }
    }

    if detect::wants_ace777_stop_help(&lower) {
        blocks.push(
            "Pour arrêter ACE777 : `./stop_ace777.sh` dans ace777-test-day1 \
             (arrêt vocal automatique non activé pour sécurité)."
                .into(),
        );
    }

    if blocks.len() <= 1 {
        return Ok(String::new());
    }

    Ok(format!(
        "{}\n\n\
         [Consignes ACE777]\n\
         - Réponds en français à partir de ces données locales uniquement.\n\
         - Ne invente aucun PnL ni statut absent ci-dessus.\n\
         - BETA = SCOUT SHORT, ALPHA = HUNTER LONG.\n\
         ---\n",
        blocks.join("\n\n")
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn gather_context_ok() {
        let r = gather_context("quel est le statut beta sur ace777");
        assert!(r.is_ok());
        let s = r.unwrap();
        assert!(s.contains("ACE777") || s.contains("introuvable"));
    }
}

